"use client"

// Bollard UI — commit-secret-guard · MIT licence · https://bollard-ui.vercel.app/components/commit-secret-guard

import * as React from "react"
import { CircleAlert, CircleCheck, ExternalLink, EyeOff, FileKey, Loader2, RotateCcwKey, ShieldAlert, TriangleAlert, Undo2 } from "lucide-react"

import { cn } from "@/lib/utils"
import { DEFAULT_FIXTURE_PATTERNS, envReference, moveToEnvPatch, scanDiffForSecrets, type SecretFinding } from "./scan-diff"

export { DEFAULT_FIXTURE_PATTERNS, envReference, globToRegExp, maskSecret, moveToEnvPatch, parseUnifiedDiff, scanDiffForSecrets, shannonEntropy, type DiffFile, type FindingKind, type SecretFinding } from "./scan-diff"

export type SecretResolution = "removed" | "moved" | "allowed"
/** What the caller should apply for a resolution. */
export type SecretFix =
  | { kind: "replace-line"; file: string; line: number; text: string; envName: string; /** Last line replaced, for a multi-line private key. */ endLine?: number }
  | { kind: "remove-line"; file: string; line: number; /** Last line removed, for a multi-line private key. */ endLine?: number }
  | { kind: "command"; command: string }
  | { kind: "allow"; id: string }

/** Every visible string. `{count}`, `{lines}`, `{file}`, `{line}`, `{name}`, `{ref}`, `{label}`, `{patterns}` are filled in. */
export const COMMIT_SECRET_MESSAGES = {
  title: "Secrets in this change",
  stagePre: "Before commit",
  stagePushed: "Already pushed",
  clean: "No secrets in {lines} added lines.",
  found: "{count} to fix in the added lines. The commit waits until each one is handled.",
  allDone: "All handled. Nothing secret goes into this commit.",
  rotate: "This is already on the remote. Rotate it now: deleting it in a new commit leaves it in the history and in every clone.",
  rotateLink: "Rotate key",
  fixture: "In a test fixture, but it's a live key format.",
  moveToEnv: "Move to env",
  remove: "Remove line",
  unstage: "Unstage and ignore",
  falsePositive: "Not a secret",
  undo: "Undo",
  movedNote: "Line {line} reads {ref}. Put the value in .env as {name} (keep .env git-ignored).",
  removedNote: "Line {line} is dropped from the commit.",
  removedBlockNote: "Lines {line}–{end} are dropped from the commit.",
  rotateFile: "This file is already on the remote. Rotate every key in it: deleting it in a new commit leaves it in the history and in every clone.",
  unstagedNote: "Run: {command}",
  allowedNote: "Marked as not a secret. It won't be flagged again.",
  ignoredSummary: "{count} ignored: test fixtures ({patterns}) or lines marked allowed.",
  commit: "Commit",
  committing: "Committing…",
  heldHint: "Fix or dismiss each finding to commit.",
  listLabel: "Findings",
}
export type CommitSecretMessages = typeof COMMIT_SECRET_MESSAGES

const fill = (template: string, values: Record<string, string | number>) => template.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))
const fixButton = "inline-flex min-h-7 items-center gap-1 rounded-md border px-2 text-xs font-medium outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50"
const button = "inline-flex h-9 items-center justify-center gap-2 rounded-md px-4 text-sm font-medium outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50"

export interface CommitSecretGuardProps extends Omit<React.ComponentProps<"div">, "onChange" | "defaultValue"> {
  /** Unified diff to check (`git diff --cached`, or a PR's .diff). Only added lines are scanned. */
  diff: string
  /** True when these commits are already on a remote (a PR diff, a pre-push hook): every finding then says to rotate. */
  pushed?: boolean
  /** Globs for test fixtures. Generic and entropy hits there are ignored; live provider keys are still flagged. */
  fixturePatterns?: string[]
  /** Controlled resolutions by finding id. */
  value?: Record<string, SecretResolution>
  /** Initial resolutions when uncontrolled, e.g. ids your allowlist already holds as "allowed". */
  defaultValue?: Record<string, SecretResolution>
  /** Called with all resolutions whenever one changes. */
  onValueChange?: (value: Record<string, SecretResolution>) => void
  /** Called with what to apply when a finding is resolved: a replacement line, a removed line, a git command or an allowlist id. */
  onResolve?: (finding: SecretFinding, resolution: SecretResolution, fix: SecretFix) => void
  /** Shows the commit button; enabled once every finding is handled. May return a Promise for a pending state. */
  onCommit?: () => void | Promise<void>
  /** Any visible string. */
  messages?: Partial<CommitSecretMessages>
}

/**
 * Prevents committing a credential. It scans only the lines a diff adds for provider keys, private keys, passwords in
 * URLs, hard-coded secrets and high-entropy strings, flags .env and key files, ignores test fixtures by pattern (except
 * live key formats), and offers per-finding fixes: move to an env variable, remove the line, or mark a false positive.
 * When the change is already pushed it says to rotate the key, because a later commit can't take it out of history.
 */
export function CommitSecretGuard({ diff, pushed = false, fixturePatterns = DEFAULT_FIXTURE_PATTERNS, value, defaultValue = {}, onValueChange, onResolve, onCommit, messages, className, ...props }: CommitSecretGuardProps) {
  const t = { ...COMMIT_SECRET_MESSAGES, ...messages }
  const findings = React.useMemo(() => scanDiffForSecrets(diff, fixturePatterns), [diff, fixturePatterns])
  const addedLines = React.useMemo(() => (typeof diff === "string" ? diff.split("\n").filter((l) => l.startsWith("+") && !l.startsWith("+++ ")).length : 0), [diff])
  const [inner, setInner] = React.useState(defaultValue)
  const resolved = value ?? inner
  const [pending, setPending] = React.useState(false)
  const [announce, setAnnounce] = React.useState("")
  const busy = React.useRef(false)
  const list = React.useRef<HTMLUListElement>(null)
  const commitRef = React.useRef<HTMLButtonElement>(null)
  const refocus = React.useRef<string | null>(null)
  const id = React.useId()

  const ignored = findings.filter((f) => f.allowed || (f.fixture && f.kind !== "provider" && f.kind !== "file"))
  const active = findings.filter((f) => !ignored.includes(f))
  const open = active.filter((f) => !resolved[f.id])
  const summary = !active.length ? fill(t.clean, { lines: addedLines }) : open.length ? fill(t.found, { count: open.length }) : t.allDone

  // One announcement after the diff settles, never one per keystroke.
  React.useEffect(() => {
    const timer = setTimeout(() => setAnnounce(summary), 700)
    return () => clearTimeout(timer)
  }, [summary])
  // The tapped row changes shape, so focus moves to the next open fix, or to Commit when none is left.
  React.useEffect(() => {
    if (refocus.current === null) return
    const row = [...(list.current?.querySelectorAll<HTMLElement>("li[data-row]") ?? [])].find((li) => li.dataset.row === refocus.current)
    const target = row?.querySelector<HTMLButtonElement>("button[data-fix]")
    ;(target ?? (commitRef.current && !commitRef.current.disabled ? commitRef.current : list.current))?.focus()
    refocus.current = null
  }, [resolved])

  const set = (next: Record<string, SecretResolution>) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  // Single-quoted so paths with spaces or $ survive the shell; .gitignore gets a leading / so only this path is ignored.
  const sq = (text: string) => `'${text.replace(/'/g, "'\\''")}'`
  const fileCommand = (f: SecretFinding) => `git rm --cached -- ${sq(f.file)} && echo ${sq("/" + f.file)} >> .gitignore`
  const resolve = (f: SecretFinding, resolution: SecretResolution) => {
    const at = active.indexOf(f)
    const next = [...active.slice(at + 1), ...active.slice(0, at)].find((a) => !resolved[a.id])
    refocus.current = next?.id ?? ""
    set({ ...resolved, [f.id]: resolution })
    const fix: SecretFix =
      resolution === "allowed" ? { kind: "allow", id: f.id }
      : f.kind === "file" ? { kind: "command", command: fileCommand(f) }
      : resolution === "moved" ? { kind: "replace-line", file: f.file, line: f.line, text: moveToEnvPatch(f, f.source), envName: f.envName, ...(f.endLine > f.line && { endLine: f.endLine }) }
      : { kind: "remove-line", file: f.file, line: f.line, ...(f.endLine > f.line && { endLine: f.endLine }) }
    onResolve?.(f, resolution, fix)
  }
  const undo = (f: SecretFinding) => {
    const next = { ...resolved }
    delete next[f.id]
    refocus.current = f.id
    set(next)
  }
  const commit = async () => {
    if (!onCommit || open.length || busy.current) return
    busy.current = true
    setPending(true)
    try {
      await onCommit()
    } catch {
      // The caller reports commit failures; the button becomes usable again.
    } finally {
      busy.current = false
      setPending(false)
    }
  }

  return (
    <div data-slot="commit-secret-guard" data-state={open.length ? "blocked" : "clear"} className={cn("w-full max-w-lg min-w-0 overflow-hidden rounded-xl border bg-background text-sm", className)} {...props}>
      <div className="flex items-center gap-2 border-b px-4 py-3">
        <ShieldAlert aria-hidden className="size-4 shrink-0 text-muted-foreground" />
        <h3 className="min-w-0 flex-1 font-medium">{t.title}</h3>
        <span className={cn("rounded-md border px-1.5 py-0.5 text-xs font-medium", pushed ? "border-red-500/30 bg-red-500/10 text-red-700 dark:text-red-300" : "text-muted-foreground")}>{pushed ? t.stagePushed : t.stagePre}</span>
      </div>

      <div className="grid grid-cols-[minmax(0,1fr)] gap-3 px-4 py-3">
        <p id={`${id}-summary`} className={cn("flex gap-2 rounded-md border p-3 font-medium", open.length ? "border-red-500/30 bg-red-500/5 text-red-800 dark:text-red-300" : "border-emerald-500/30 bg-emerald-500/5 text-emerald-800 dark:text-emerald-300")}>
          {open.length ? <CircleAlert aria-hidden className="mt-0.5 size-4 shrink-0" /> : <CircleCheck aria-hidden className="mt-0.5 size-4 shrink-0" />}
          <span className="min-w-0">{summary}</span>
        </p>

        {active.length > 0 && (
          <ul ref={list} tabIndex={-1} aria-label={t.listLabel} className="divide-y rounded-md border outline-none">
            {active.map((f) => {
              const done = resolved[f.id]
              const where = f.line ? `${f.file}:${f.line}${f.endLine > f.line ? `–${f.endLine}` : ""}` : f.file
              const ref = envReference(f.file, f.envName)
              return (
                <li key={f.id} data-row={f.id} data-resolution={done ?? "open"} className={cn("grid gap-1.5 px-3 py-2.5", !done && f.severity === "high" && "bg-red-500/5")}>
                  <div className="flex min-w-0 flex-wrap items-baseline gap-x-2 gap-y-0.5">
                    <span className="flex min-w-0 items-start gap-1.5">
                      <span className="flex h-5 shrink-0 items-center">
                        {done ? <CircleCheck aria-hidden className="size-3.5 shrink-0 text-emerald-600 dark:text-emerald-400" /> : f.kind === "file" ? <FileKey aria-hidden className="size-3.5 shrink-0 text-red-600 dark:text-red-400" /> : <TriangleAlert aria-hidden className={cn("size-3.5 shrink-0 self-center", f.severity === "high" ? "text-red-600 dark:text-red-400" : "text-amber-600 dark:text-amber-400")} />}
                      </span>
                      <span className={cn("font-medium", done && "text-muted-foreground line-through decoration-1")}>{f.label}</span>
                    </span>
                    <span className="min-w-0 font-mono text-xs text-muted-foreground [overflow-wrap:anywhere]">{where}</span>
                  </div>
                  {f.preview && !done && <code className="block rounded bg-muted px-2 py-1 font-mono text-xs [overflow-wrap:anywhere] whitespace-pre-wrap">{f.preview.trim()}</code>}
                  {f.fixture && !done && <p className="text-xs text-amber-800 dark:text-amber-300">{t.fixture}</p>}
                  {pushed && done !== "allowed" && (
                    <p className="flex flex-wrap items-start gap-x-2 gap-y-1 text-xs text-red-700 dark:text-red-400">
                      <RotateCcwKey aria-hidden className="mt-0.5 size-3.5 shrink-0" />
                      <span className="min-w-0 flex-1">{f.kind === "file" ? t.rotateFile : t.rotate}</span>
                      {f.rotateUrl && <a href={f.rotateUrl} target="_blank" rel="noreferrer noopener" className="inline-flex items-center gap-1 rounded-sm font-medium underline outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50">{t.rotateLink}<ExternalLink aria-hidden className="size-3" /></a>}
                    </p>
                  )}
                  {done ? (
                    <div className="flex flex-wrap items-start gap-2 text-xs text-muted-foreground">
                      <span className="min-w-0 flex-1 [overflow-wrap:anywhere]">
                        {done === "allowed" ? t.allowedNote : f.kind === "file" ? fill(t.unstagedNote, { command: fileCommand(f) }) : done === "moved" ? fill(t.movedNote, { line: f.line, ref, name: f.envName }) : fill(f.endLine > f.line ? t.removedBlockNote : t.removedNote, { line: f.line, end: f.endLine })}
                      </span>
                      <button type="button" data-fix="" onClick={() => undo(f)} className={cn(fixButton, "hover:bg-accent")}>
                        <Undo2 aria-hidden className="size-3.5" />
                        {t.undo}
                      </button>
                    </div>
                  ) : (
                    <div className="flex flex-wrap gap-1.5">
                      {/* A multi-line key block can't become one env lookup in place; remove it instead. */}
                      {f.kind !== "file" && f.endLine === f.line && <button type="button" data-fix="" onClick={() => resolve(f, "moved")} className={cn(fixButton, "border-red-500/40 text-red-800 hover:bg-red-500/10 dark:text-red-200")}>{t.moveToEnv}</button>}
                      <button type="button" data-fix="" onClick={() => resolve(f, "removed")} className={cn(fixButton, "hover:bg-accent")}>{f.kind === "file" ? t.unstage : t.remove}</button>
                      <button type="button" data-fix="" onClick={() => resolve(f, "allowed")} className={cn(fixButton, "border-transparent text-muted-foreground hover:bg-accent hover:text-foreground")}>
                        <EyeOff aria-hidden className="size-3.5" />
                        {t.falsePositive}
                      </button>
                    </div>
                  )}
                </li>
              )
            })}
          </ul>
        )}
        {ignored.length > 0 && <p className="text-xs text-muted-foreground [overflow-wrap:anywhere]">{fill(t.ignoredSummary, { count: ignored.length, patterns: fixturePatterns.slice(0, 3).join(", ") + (fixturePatterns.length > 3 ? "…" : "") })}</p>}
      </div>

      <span role="status" className="sr-only">{announce}</span>
      {onCommit && (
        <div className="flex flex-wrap items-center justify-end gap-2 border-t px-4 py-3">
          {open.length > 0 && <span id={`${id}-held`} className="mr-auto text-xs text-muted-foreground">{t.heldHint}</span>}
          <button ref={commitRef} type="button" onClick={commit} disabled={open.length > 0 || pending} aria-busy={pending || undefined} aria-describedby={open.length ? `${id}-held` : `${id}-summary`} className={cn(button, "bg-primary text-primary-foreground hover:bg-primary/90")}>
            {pending && <Loader2 aria-hidden className="size-4 animate-spin" />}
            {pending ? t.committing : t.commit}
          </button>
        </div>
      )}
    </div>
  )
}

// Bollard UI — commit-secret-guard · MIT licence · https://bollard-ui.vercel.app/components/commit-secret-guard

// Pure unified-diff parsing and secret scanning of added lines only. Safe on the server.

export interface DiffFile {
  path: string
  isNew: boolean
  deleted: boolean
  binary: boolean
  /** Renamed or copied here from another path (`rename to`). */
  renamed: boolean
  /** Added lines with their line number in the new file. */
  added: { line: number; text: string }[]
}

export type FindingKind = "provider" | "generic" | "entropy" | "file"

export interface SecretFinding {
  /** Stable across re-scans: file + rule + a hash of the value (never the value itself). */
  id: string
  file: string
  /** Line in the new file; 0 for whole-file findings. */
  line: number
  /** Last line of a multi-line secret (a PEM private key block). Equal to `line` otherwise. */
  endLine: number
  rule: string
  /** e.g. "Stripe live secret key", ".env file". */
  label: string
  kind: FindingKind
  severity: "high" | "medium"
  /** The matched secret. Show `masked` instead. */
  value: string
  masked: string
  /** The added line with the secret masked. */
  preview: string
  /** The added line as written (contains the secret). Use it to build a patch, never to display. */
  source: string
  /** Suggested environment variable name. */
  envName: string
  /** Matched a fixture pattern; generic and entropy hits there are ignored, live provider keys are not. */
  fixture: boolean
  /** The line carries an allow marker (gitleaks:allow, pragma: allowlist secret). */
  allowed: boolean
  /** Where to revoke it, when known. */
  rotateUrl?: string
}

export const DEFAULT_FIXTURE_PATTERNS = ["**/__tests__/**", "**/*.test.*", "**/*.spec.*", "**/fixtures/**", "**/testdata/**", "**/__mocks__/**", "**/*.snap"]

type Rule = { id: string; label: string; re: RegExp; env: string; rotate?: string; severity?: "high" | "medium"; group?: number }
const RULES: Rule[] = [
  { id: "private-key", label: "Private key", re: /-----BEGIN (?:[A-Z0-9]+ )*PRIVATE KEY(?: BLOCK)?-----/, env: "PRIVATE_KEY" },
  { id: "aws-access-key", label: "AWS access key ID", re: /\b(?:AKIA|ASIA)[0-9A-Z]{16}\b/, env: "AWS_ACCESS_KEY_ID", rotate: "https://console.aws.amazon.com/iam/home#/security_credentials" },
  { id: "aws-secret", label: "AWS secret access key", re: /aws_?secret_?access_?key["']?\s*[:=]\s*["']?([A-Za-z0-9/+=]{40})\b/i, group: 1, env: "AWS_SECRET_ACCESS_KEY", rotate: "https://console.aws.amazon.com/iam/home#/security_credentials" },
  { id: "github-token", label: "GitHub token", re: /\bgh[pousr]_[A-Za-z0-9]{36,}\b|\bgithub_pat_[A-Za-z0-9_]{22,}/, env: "GITHUB_TOKEN", rotate: "https://github.com/settings/tokens" },
  { id: "gitlab-token", label: "GitLab token", re: /\bglpat-[A-Za-z0-9_-]{20,}/, env: "GITLAB_TOKEN", rotate: "https://gitlab.com/-/user_settings/personal_access_tokens" },
  { id: "stripe-live", label: "Stripe live secret key", re: /\b[sr]k_live_[A-Za-z0-9]{16,}/, env: "STRIPE_SECRET_KEY", rotate: "https://dashboard.stripe.com/apikeys" },
  { id: "stripe-test", label: "Stripe test key", re: /\b[sr]k_test_[A-Za-z0-9]{16,}/, env: "STRIPE_SECRET_KEY", severity: "medium" },
  { id: "stripe-webhook", label: "Stripe webhook secret", re: /\bwhsec_[A-Za-z0-9]{24,}/, env: "STRIPE_WEBHOOK_SECRET", rotate: "https://dashboard.stripe.com/webhooks" },
  { id: "slack-token", label: "Slack token", re: /\bxox[abprs]-[A-Za-z0-9-]{10,}/, env: "SLACK_TOKEN", rotate: "https://api.slack.com/apps" },
  { id: "slack-webhook", label: "Slack webhook URL", re: /https:\/\/hooks\.slack\.com\/services\/T[A-Z0-9]+\/B[A-Z0-9]+\/[A-Za-z0-9]{20,}/, env: "SLACK_WEBHOOK_URL" },
  { id: "anthropic", label: "Anthropic API key", re: /\bsk-ant-[A-Za-z0-9_-]{20,}/, env: "ANTHROPIC_API_KEY", rotate: "https://platform.claude.com/settings/keys" },
  { id: "openai", label: "OpenAI API key", re: /\bsk-(?:proj-|svcacct-|admin-)?[A-Za-z0-9_-]{20,}/, env: "OPENAI_API_KEY", rotate: "https://platform.openai.com/api-keys" },
  { id: "google-api", label: "Google API key", re: /\bAIza[0-9A-Za-z_-]{35}/, env: "GOOGLE_API_KEY", rotate: "https://console.cloud.google.com/apis/credentials" },
  { id: "google-oauth", label: "Google OAuth client secret", re: /\bGOCSPX-[A-Za-z0-9_-]{20,}/, env: "GOOGLE_CLIENT_SECRET", rotate: "https://console.cloud.google.com/apis/credentials" },
  { id: "npm-token", label: "npm token", re: /\bnpm_[A-Za-z0-9]{36}\b/, env: "NPM_TOKEN", rotate: "https://www.npmjs.com/settings/~/tokens" },
  { id: "npmrc-auth", label: "npm auth token", re: /_authToken\s*=\s*(?!\$\{)([^\s"']{8,})/, group: 1, env: "NPM_TOKEN" },
  { id: "sendgrid", label: "SendGrid API key", re: /\bSG\.[A-Za-z0-9_-]{22}\.[A-Za-z0-9_-]{43}\b/, env: "SENDGRID_API_KEY", rotate: "https://app.sendgrid.com/settings/api_keys" },
  { id: "jwt", label: "JSON Web Token", re: /\beyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{10,}/, env: "AUTH_TOKEN", severity: "medium" },
  { id: "url-password", label: "Password in a connection URL", re: /\b[a-z][a-z0-9+.-]*:\/\/[^\s:@/'"]+:([^\s@/'"]{3,})@[^\s'"]+/i, group: 1, env: "DATABASE_URL" },
]
const GENERIC = /([A-Za-z0-9_.-]*(?:secret|token|passw(?:or)?d|pwd|api[_-]?key|apikey|auth[_-]?key|credential|private[_-]?key|access[_-]?key|client[_-]?secret)[A-Za-z0-9_.-]*)["']?\s*(?:[:=]|=>|:=)\s*(["'`])([^"'`\s]{8,})\2/i
const ENV_LINE = /^\s*(?:export\s+)?([A-Z0-9_]*(?:SECRET|TOKEN|PASSWORD|PASSWD|API_KEY|APIKEY|PRIVATE_KEY|ACCESS_KEY|CREDENTIALS?)[A-Z0-9_]*)\s*=\s*["']?([^\s"'#]{8,})/
const PLACEHOLDER = /^(?:x+|\*+|\.+|-+|<.*>|\$\{.*\}|\$[A-Z_]+|\{\{.*\}\}|%[\w]+%|your[\w-]*|changeme|change[_-]?me|placeholder|dummy|fake|redacted|null|undefined|none|todo|secret|password|token|test[\w-]*|example[\w-]*|.*EXAMPLE.*|.*x{6,}.*|(process\.env|os\.environ|import\.meta\.env|ENV\[|getenv|System\.getenv).*)$/i
const ALLOW = /gitleaks:allow|pragma:\s*allowlist secret|secret-guard:allow/i
const SKIP_ENTROPY = /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|bun\.lockb?|go\.sum|Cargo\.lock|composer\.lock|poetry\.lock|Gemfile\.lock)$|\.(min\.js|map|svg|snap)$/i
const ENV_FILE = /(^|\/)\.env(\.[\w.-]+)?$/i
const ENV_EXAMPLE = /\.env\.(example|sample|template|dist|defaults)$/i
const KEY_FILE = /(^|\/)(id_(rsa|dsa|ecdsa|ed25519)|[^/]+\.(pem|key|p12|pfx|jks|keystore|ppk)|\.git-credentials|credentials\.json|service[-_]?account[^/]*\.json)$/i

export function shannonEntropy(text: string) {
  const counts = new Map<string, number>()
  for (const ch of text) counts.set(ch, (counts.get(ch) ?? 0) + 1)
  let bits = 0
  for (const n of counts.values()) bits -= (n / text.length) * Math.log2(n / text.length)
  return bits
}

const hash = (text: string) => {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 0x01000193)
  return (h >>> 0).toString(16).padStart(8, "0")
}
export const maskSecret = (value: string) => (value.length <= 10 ? "•".repeat(Math.max(4, value.length)) : `${value.slice(0, 4)}${"•".repeat(Math.min(12, value.length - 8))}${value.slice(-4)}`)
/** Undo git's C-style path quoting, octal UTF-8 bytes included: "caf\303\251.env" → café.env */
const unquote = (p: string) => {
  if (!p.startsWith('"') || !p.endsWith('"') || p.length < 2) return p
  const map: Record<string, number> = { n: 10, t: 9, r: 13, b: 8, f: 12, v: 11, a: 7 }
  const bytes: number[] = []
  const body = p.slice(1, -1)
  for (let i = 0; i < body.length; i++) {
    if (body[i] === "\\" && /^[0-7]{3}$/.test(body.slice(i + 1, i + 4))) bytes.push(parseInt(body.slice(i + 1, (i += 3) + 1), 8))
    else if (body[i] === "\\" && i + 1 < body.length) bytes.push(map[body[++i]] ?? body.charCodeAt(i))
    else bytes.push(...new TextEncoder().encode(body[i]))
  }
  return new TextDecoder().decode(new Uint8Array(bytes))
}

/** "**\/fixtures/**", "*.test.*" style globs. A pattern without a slash matches the file name anywhere. */
export function globToRegExp(glob: string) {
  const body = glob.replace(/^\.\//, "").replace(/[.+^$()|[\]\\]/g, "\\$&").replace(/\*\*\//g, "\u0000").replace(/\*\*/g, "\u0001").replace(/\*/g, "[^/]*").replace(/\?/g, "[^/]").replace(/\u0000/g, "(?:.*/)?").replace(/\u0001/g, ".*")
  return new RegExp(glob.includes("/") ? `^${body}$` : `(?:^|/)${body}$`)
}

/** Reads a unified diff (git diff --cached, a PR .diff). CRLF and BOM tolerated; garbage gives no files. */
export function parseUnifiedDiff(input: unknown): DiffFile[] {
  if (typeof input !== "string") return []
  const files: DiffFile[] = []
  let file: DiffFile | null = null
  let header = false // between "diff --git" and the first hunk
  let next = 0
  let prev = ""
  // Lines left in the current hunk, from its @@ header. Inside a hunk "--- x" / "+++ y" are content, not headers.
  let oldLeft = 0
  let newLeft = 0
  for (const raw of input.replace(/^\uFEFF/, "").slice(0, 5_000_000).split("\n")) {
    const before = prev
    const line = raw.endsWith("\r") ? raw.slice(0, -1) : raw
    prev = line
    if (oldLeft > 0 || newLeft > 0) {
      if (line.startsWith("+")) {
        file!.added.push({ line: next++, text: line.slice(1) })
        newLeft--
        continue
      }
      if (line.startsWith("-")) {
        oldLeft--
        continue
      }
      if (line.startsWith(" ") || line === "") {
        next++
        oldLeft--
        newLeft--
        continue
      }
      if (line.startsWith("\\")) continue
      oldLeft = newLeft = 0 // A hand-trimmed hunk ended early.
    }
    if (line.startsWith("diff --git ")) {
      const m = line.match(/^diff --git "?a\/(.+?)"? "?b\/(.+?)"?$/)
      file = { path: unquote(m?.[2] ?? ""), isNew: false, deleted: false, binary: false, renamed: false, added: [] }
      files.push(file)
      header = true
    } else if (line.startsWith("+++ ") && (header || !file || before.startsWith("--- "))) {
      // Plain `diff -u` output has no "diff --git" line, so a +++ outside a header starts a new file.
      if (!header) {
        file = { path: "", isNew: false, deleted: false, binary: false, renamed: false, added: [] }
        files.push(file)
      }
      const p = line.slice(4).replace(/\t.*$/, "")
      if (p === "/dev/null") file!.deleted = true
      else file!.path = unquote(p).replace(/^b\//, "")
      header = true
    } else if (file && header && line.startsWith("new file mode")) file.isNew = true
    else if (file && header && line.startsWith("deleted file mode")) file.deleted = true
    else if (file && header && /^(rename|copy) to /.test(line)) {
      file.renamed = true
      file.path = unquote(line.replace(/^(rename|copy) to /, ""))
    } else if (file && /^(Binary files .* differ|GIT binary patch)$/.test(line)) file.binary = true
    else if (line.startsWith("@@")) {
      const h = line.match(/^@@+ -\d+(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/)
      next = Number(h?.[2] ?? line.match(/\+(\d+)/)?.[1] ?? 1)
      if (h && file) {
        oldLeft = Number(h[1] ?? 1)
        newLeft = Number(h[3] ?? 1)
      }
      header = false
    } else if (file && !header && line.startsWith("+")) file.added.push({ line: next++, text: line.slice(1) })
    else if (file && !header && (line.startsWith(" ") || line === "")) next++
  }
  return files.filter((f) => f.path)
}

const screaming = (name: string) => name.replace(/([a-z0-9])([A-Z])/g, "$1_$2").replace(/[^A-Za-z0-9]+/g, "_").replace(/^_+|_+$/g, "").toUpperCase()

/** Scans only what the diff adds. Fixture files skip generic and entropy hits; live provider keys are flagged anywhere. */
export function scanDiffForSecrets(input: unknown, fixturePatterns: string[] = DEFAULT_FIXTURE_PATTERNS): SecretFinding[] {
  const fixtures = fixturePatterns.map(globToRegExp)
  const out: SecretFinding[] = []
  for (const f of parseUnifiedDiff(input)) {
    if (f.deleted) continue
    const fixture = fixtures.some((re) => re.test(f.path))
    const push = (partial: Omit<SecretFinding, "id" | "file" | "masked" | "fixture" | "preview" | "source" | "endLine"> & { preview?: string; endLine?: number }) => {
      const masked = maskSecret(partial.value)
      const id = `${f.path}:${partial.rule}:${hash(partial.value)}`
      if (out.some((o) => o.id === id && o.line === partial.line)) return
      out.push({ ...partial, endLine: partial.endLine ?? partial.line, id: out.some((o) => o.id === id) ? `${id}:${partial.line}` : id, file: f.path, masked, fixture, source: partial.preview ?? "", preview: (partial.preview ?? "").split(partial.value).join(masked).slice(0, 240) })
    }
    if (ENV_FILE.test(f.path) && !ENV_EXAMPLE.test(f.path) && (f.isNew || f.renamed || f.added.length)) push({ line: 0, rule: "env-file", label: ".env file", kind: "file", severity: "high", value: f.path, envName: "", allowed: false })
    else if (KEY_FILE.test(f.path)) push({ line: 0, rule: "key-file", label: "Key or credentials file", kind: "file", severity: "high", value: f.path, envName: "", allowed: false })
    const added = f.added.slice(0, 20_000)
    for (let k = 0; k < added.length; k++) {
      const { line, text } = added[k]
      const src = text.slice(0, 4000)
      // A PEM block is one finding spanning BEGIN…END; its base64 body lines aren't scanned on their own.
      if (/-----BEGIN (?:[A-Z0-9]+ )*PRIVATE KEY(?: BLOCK)?-----/.test(src) && !/-----END [A-Z0-9 ]*PRIVATE KEY/.test(src)) {
        let end = k
        while (end + 1 < added.length && end - k < 200 && added[end + 1].line === added[end].line + 1 && !/-----END [A-Z0-9 ]*PRIVATE KEY/.test(added[end].text)) end++
        if (/-----END [A-Z0-9 ]*PRIVATE KEY/.test(added[end].text)) {
          const value = src.match(/-----BEGIN (?:[A-Z0-9]+ )*PRIVATE KEY(?: BLOCK)?-----/)![0]
          push({ line, endLine: added[end].line, rule: "private-key", label: "Private key", kind: "provider", severity: "high", value: value + added.slice(k + 1, end + 1).map((a) => a.text).join(""), envName: "PRIVATE_KEY", allowed: ALLOW.test(src), preview: src })
          k = end
          continue
        }
      }
      const allowed = ALLOW.test(src)
      const taken: string[] = []
      for (const rule of RULES) {
        const m = src.match(rule.re)
        const value = m?.[rule.group ?? 0]
        if (!value || PLACEHOLDER.test(value) || taken.some((t) => t.includes(value) || value.includes(t))) continue
        taken.push(value)
        push({ line, rule: rule.id, label: rule.label, kind: "provider", severity: rule.severity ?? "high", value, envName: rule.env, allowed, rotateUrl: rule.rotate, preview: src })
      }
      const g = src.match(GENERIC)
      const e = g || ENV_FILE.test(f.path) ? null : src.match(ENV_LINE)
      const gName = g?.[1] ?? e?.[1] ?? ""
      const gValue = g?.[3] ?? e?.[2] ?? ""
      if (gValue && !taken.some((t) => t.includes(gValue) || gValue.includes(t)) && !PLACEHOLDER.test(gValue) && shannonEntropy(gValue) >= 3) {
        taken.push(gValue)
        push({ line, rule: "generic", label: `Hard-coded ${gName.replace(/^[._-]+/, "")}`, kind: "generic", severity: "medium", value: gValue, envName: screaming(gName), allowed, preview: src })
      }
      if (fixture || SKIP_ENTROPY.test(f.path) || ENV_FILE.test(f.path)) continue
      for (const m of src.matchAll(/[A-Za-z0-9+/_-]{32,}={0,2}/g)) {
        const token = m[0]
        const mixed = /[a-z]/.test(token) && /[A-Z]/.test(token) && /\d/.test(token)
        if (!mixed || taken.some((t) => t.includes(token) || token.includes(t)) || /^sha\d+-/.test(token) || src.includes(`/${token}`) || shannonEntropy(token) < 4.3) continue
        taken.push(token)
        push({ line, rule: "entropy", label: "High-entropy string", kind: "entropy", severity: "medium", value: token, envName: "SECRET", allowed, preview: src })
      }
    }
  }
  return out
}

/** How code in this file reads an environment variable. */
export function envReference(file: string, name: string) {
  const ext = file.split(".").pop()?.toLowerCase() ?? ""
  if (/^(js|jsx|ts|tsx|mjs|cjs|vue|svelte|astro)$/.test(ext)) return `process.env.${name}`
  if (ext === "py") return `os.environ["${name}"]`
  if (ext === "go") return `os.Getenv("${name}")`
  if (ext === "rb") return `ENV["${name}"]`
  if (ext === "php") return `getenv('${name}')`
  if (ext === "java" || ext === "kt") return `System.getenv("${name}")`
  if (ext === "cs") return `Environment.GetEnvironmentVariable("${name}")`
  if (ext === "rs") return `std::env::var("${name}")`
  return `\${${name}}`
}

/** The added line with the secret (and its quotes, in code) swapped for an env lookup. */
export function moveToEnvPatch(finding: SecretFinding, line: string) {
  const ref = envReference(finding.file, finding.envName)
  const quoted = new RegExp(`(["'\`])${finding.value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\1`)
  const code = !ref.startsWith("${")
  return code && quoted.test(line) ? line.replace(quoted, ref) : line.split(finding.value).join(ref)
}
